String money(int value) => '${value ~/ 100}.${(value % 100).toString().padLeft(2, '0')}';
String signedMoney(int value) => value == 0 ? '0.00' : '${value > 0 ? '+' : '-'}${money(value.abs())}';
      case 'BALANCES':
